// ── SEGUNDO NIVEL COMERCIAL — SISTEMA ORBITAL POR CAPAS ────────────────
// Cada categoría tiene N capas. Cada capa tiene 7 marcas.
// El slot 8 siempre es "OTRO →" para avanzar a la siguiente capa.
// La última capa no muestra OTRO (no hay más).
// Capa 1 = máxima visibilidad / precio premium.
// Capa 2+ = visibilidad media / precios menores.
type OrbitBrand = {
  label: string;
  icon: keyof typeof Feather.glyphMap;
  color: string;
  url: string;
  logoUri?: string;
  logoSource?: ImageSourcePropType;
  logoBg?: string;
  fillLogo?: boolean;
  logoScale?: number;
};
// Sub-intención: categoría intermedia (ej: "RÁPIDA", "DELIVERY").
// No tiene URL propia — al pulsar entra al nivel de marcas.
type OrbitSubIntent = {
  label: string;
  icon: keyof typeof Feather.glyphMap;
  color: string;
  brands: OrbitBrand[];
};
// Categoría con navegación profunda (2 niveles: sub-intenciones → marcas).
type OrbitDeepCategory = {
  subIntents: OrbitSubIntent[];
};
const SI  = (slug: string) => `https://cdn.simpleicons.org/${slug}/ffffff`;
const SIB = (slug: string, hex: string) => `https://cdn.simpleicons.org/${slug}/${hex.replace('#', '')}`;
const IH  = (domain: string) => `https://icon.horse/icon/${domain}`;
const CLR = (domain: string) => `https://logo.clearbit.com/${domain}`;
const MCDLogo   = require("../assets/providers/mcdonalds.svg");
const BKLogo    = require("../assets/providers/burgerking.svg");
