  const [activityFilter, setActivityFilter] = useState<
    "todas" | GoActivityKey
  >("todas");
  // V1 BLOQUE — LISTADOS Y FILTROS
  // Filtro POR TIPO DE ACCIÓN (independiente del estado y la actividad).
  // El campo `type` de cada GO clasifica la acción real que el usuario
  // realiza al "enviar":
  //   • "GO"       → mensaje GO clásico (whatsapp con plantilla)
  //   • "TAREA"    → tarea personal sin envío
  //   • "LLAMADA"  → llamada al teléfono del contacto
  //   • "WHATSAPP" → mensaje suelto de WhatsApp (sin plantilla GO)
  // Por compatibilidad, los GO antiguos sin `type` definido se tratan
  // como "GO". El filtro "todos" no acota nada.
  const [typeFilter, setTypeFilter] = useState<
    "todos" | "GO" | "GO_INTERNO" | "TAREA" | "TAREA_INTERNA" | "LLAMADA"
  >("todos");
  // Vista dedicada "Listado de llamadas": se activa desde el botón 📞
