                      shadowColor: "transparent",
                      shadowOpacity: 0,
                      shadowRadius: 0,
                      shadowOffset: { width: 0, height: 0 },
                      elevation: 0,
                      borderWidth: 2,
                      borderColor: "#ffffff",
